private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) return null;
    TreeNode<T> left = node.getLeft();
    if (left == null) return node;
    // detach left's right subtree
    TreeNode<T> leftRight = left.getRight();
    node.setLeft(leftRight);
    if (leftRight != null) leftRight.setParent(node);
    // make node the right child of left
    left.setRight(node);
    // update parents
    left.setParent(node.getParent());
    node.setParent(left);
    // reconnect with grandparent
    TreeNode<T> parent = left.getParent();
    if (parent != null) {
        if (parent.getLeft() == node) parent.setLeft(left);
        else if (parent.getRight() == node) parent.setRight(left);
    }
    return left;
}

