    // Grab the first and last real nodes of the source list
    ListNodeImpl<E> first = list.head.next;
    ListNodeImpl<E> last = list.tail.prev;

    // Splice the source list's nodes into this list
    this.tail.prev.next = first;
    first.prev = this.tail.prev;
    this.tail.prev = last;
    last.next = this.tail;

    // Update sizes
