        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    if (message == null) {
        // Write a zero-length message
        out.write(0);
        return 0;
    }
    buffer.clear();
    schema.writeTo(buffer, message);
    byte[] bytes = buffer.getArray();
    int pos = buffer.getPosition();
    // Write the length prefix as a varint
    int size = pos;
    while ((size & ~0x7F) != 0) {
        out.write((size & 0x7F) | 0x80);
        size >>>= 7;
    }
    out.write(size);
    // Write the message bytes
    out.write(bytes, 0, pos);
    return pos;
}

